update ai_unified_session
set end_time = #{endTime}, active_flag = '0'
where biz_type = #{bizType} and biz_id = #{bizId}

update ai_unified_session
set last_heartbeat = #{heartbeat}
where biz_type = #{bizType} and biz_id = #{bizId} and active_flag = '1'

mapper.select:
select 
from ai_unified_session
where active_flag = '1'
  and expire_time is not null and expire_time < #{now}
order by expire_time asc
limit #{limit}

